4|public enum SecureMaterializationError: Error, Equatable, Sendable {
5|    case invalidRoot
6|    case fileExists
7|    case io(Int32)
8|}
9|
10|public final class SecureFileWriter {
11|    private var descriptor: Int32
12|
13|    fileprivate init(descriptor: Int32) {
14|        self.descriptor = descriptor
15|    }
16|
17|    public func write(_ data: Data) throws {
18|        guard descriptor >= 0 else {
19|            throw SecureMaterializationError.io(EBADF)
20|        }
21|        try data.withUnsafeBytes { bytes in
22|            var offset = 0
23|            while offset < bytes.count {
24|                guard let baseAddress = bytes.baseAddress else { break }
25|                let result = Darwin.write(
26|                    descriptor,
27|                    baseAddress.advanced(by: offset),
28|                    bytes.count - offset
29|                )
30|                if result < 0 {
31|                    if errno == EINTR { continue }
32|                    throw SecureMaterializationError.io(errno)
33|                }
34|                guard result > 0 else {
35|                    throw SecureMaterializationError.io(EIO)
36|                }
37|                offset += result
38|            }
39|        }
40|    }
41|
42|    fileprivate func invalidate() {
43|        descriptor = -1
44|    }
45|}
