47|public struct SecureFileMaterializer: Sendable {
48|    public let rootURL: URL
49|
50|    public init(rootURL: URL) {
51|        self.rootURL = rootURL
52|    }
53|
54|    public func write(_ data: Data, relativePath: String) throws -> URL {
55|        try write(relativePath: relativePath) { writer in
56|            try writer.write(data)
57|        }
58|    }
59|
60|    public func write(
61|        relativePath: String,
62|        contents: (SecureFileWriter) throws -> Void
63|    ) throws -> URL {
64|        try ArchivePathPolicy().validate(relativePath)
65|        let components = relativePath.split(separator: "/", omittingEmptySubsequences: false).map(String.init)
66|        guard let leaf = components.last else {
67|            throw ArchiveSecurityError.emptyComponent
68|        }
69|
70|        let rootFD = rootURL.withUnsafeFileSystemRepresentation { path -> Int32 in
71|            guard let path else { return -1 }
72|            return Darwin.open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW)
73|        }
74|        guard rootFD >= 0 else {
75|            throw SecureMaterializationError.invalidRoot
76|        }
77|
78|        var directoryDescriptors = [rootFD]
79|        defer {
80|            for descriptor in directoryDescriptors.reversed() {
81|                Darwin.close(descriptor)
82|            }
83|        }
84|
85|        var parentFD = rootFD
86|        for component in components.dropLast() {
87|            let mkdirResult = component.withCString { name in
88|                mkdirat(parentFD, name, mode_t(0o700))
89|            }
90|            if mkdirResult != 0 && errno != EEXIST {
91|                throw SecureMaterializationError.io(errno)
92|            }
93|            let childFD = component.withCString { name in
94|                openat(parentFD, name, O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW)
95|            }
96|            guard childFD >= 0 else {
97|                throw SecureMaterializationError.io(errno)
98|            }
99|            directoryDescriptors.append(childFD)
100|            parentFD = childFD
101|        }
102|
103|        var leafFD = leaf.withCString { name in
104|            openat(
105|                parentFD,
106|                name,
107|                O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC | O_NOFOLLOW,
108|                mode_t(0o600)
109|            )
110|        }
111|        guard leafFD >= 0 else {
112|            if errno == EEXIST { throw SecureMaterializationError.fileExists }
113|            throw SecureMaterializationError.io(errno)
114|        }
115|
116|        var published = false
117|        defer {
118|            if leafFD >= 0 { Darwin.close(leafFD) }
119|            if !published {
120|                _ = leaf.withCString { name in unlinkat(parentFD, name, 0) }
121|            }
122|        }
123|
124|        let writer = SecureFileWriter(descriptor: leafFD)
125|        defer { writer.invalidate() }
126|        try contents(writer)
127|
128|        guard fsync(leafFD) == 0 else {
129|            throw SecureMaterializationError.io(errno)
130|        }
131|        guard Darwin.close(leafFD) == 0 else {
132|            leafFD = -1
133|            throw SecureMaterializationError.io(errno)
134|        }
135|        leafFD = -1
136|        guard fsync(parentFD) == 0 else {
137|            throw SecureMaterializationError.io(errno)
138|        }
139|        published = true
140|        return rootURL.appending(path: relativePath)
141|    }
142|}
