3|public enum ArchiveSecurityError: Error, Equatable, Sendable {
4|    case absolutePath
5|    case parentTraversal
6|    case emptyComponent
7|    case controlCharacter
8|}
9|
10|/// Validates only the structural form of an archive member path.
11|///
12|/// Filesystem publication must independently enforce descriptor-rooted
13|/// containment and link safety after extraction.
14|public struct ArchivePathPolicy: Sendable {
15|    public init() {}
16|
17|    public func validate(_ path: String) throws {
18|        if path.hasPrefix("/") {
19|            throw ArchiveSecurityError.absolutePath
20|        }
21|        if path.unicodeScalars.contains(where: { $0.value < 0x20 || $0.value == 0x7f }) {
22|            throw ArchiveSecurityError.controlCharacter
23|        }
24|
25|        let components = path.split(separator: "/", omittingEmptySubsequences: false)
26|        if components.contains(where: \.isEmpty) {
27|            throw ArchiveSecurityError.emptyComponent
28|        }
29|        if components.contains("..") {
30|            throw ArchiveSecurityError.parentTraversal
31|        }
32|    }
33|}
